// Takes the form fields or the JSON body of the API webhook and checks them.
// The receiving addresses are NOT taken from here: they come from "Settings",
// which only the workflow owner edits.
const src = $input.first().json;
const fromApi = src && typeof src === 'object' && 'headers' in src && 'body' in src;
const b = fromApi ? (src.body || {}) : src;
const pick = (...keys) => {
  for (const k of keys) {
    const v = b[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
const clientName = pick('clientName', 'Client name');
const clientEmail = pick('clientEmail', 'Client email').toLowerCase();
const amount = Number(pick('amount', 'Amount').replace(',', '.'));
const currency = pick('currency', 'Currency').toUpperCase();
const description = pick('description', 'What is it for');
let invoiceId = pick('invoiceId', 'Invoice number (optional)');

const errors = [];
if (!clientName) errors.push('clientName is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clientEmail)) errors.push('clientEmail must be an email address');
if (!(amount > 0)) errors.push('amount must be a number above 0');
if (!/^[A-Z]{3}$/.test(currency)) errors.push('currency must be a 3-letter code such as EUR, USD or SEK');
if (invoiceId && !/^[A-Za-z0-9._-]{1,64}$/.test(invoiceId)) errors.push('invoiceId may only use letters, digits, dot, dash and underscore (max 64)');
if (!invoiceId) {
  const day = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  invoiceId = 'INV-' + day + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
}

return [{
  json: {
    ok: errors.length === 0,
    viaForm: !fromApi,
    statusCode: errors.length ? 400 : 200,
    title: errors.length ? 'Invoice not created' : '',
    message: errors.join('; '),
    clientName,
    clientEmail,
    amount: Math.round(amount * 100) / 100,
    currency,
    description,
    invoiceId,
  },
}];

// Builds the POST /api/v1/payment-requests body from the invoice and YOUR addresses in "Settings".
// USDT is only offered on Solana (send21 supports USDT on Solana and Ethereum only).
const j = $input.first().json;
const options = [];
if (j.solanaAddress) {
  options.push({ currency: 'Usdc', network: 'Solana', address: j.solanaAddress });
  options.push({ currency: 'Usdt', network: 'Solana', address: j.solanaAddress });
}
if (j.baseAddress) {
  options.push({ currency: 'Usdc', network: 'Base', address: j.baseAddress });
  options.push({ currency: 'Eurc', network: 'Base', address: j.baseAddress });
}
if (j.lightningAddress) {
  options.push({ currency: 'Btc', network: 'Mainnet', address: j.lightningAddress, method: 'Lightning' });
}
if (!options.length) {
  return [{ json: { ...j, ok: false, statusCode: 500, title: 'Invoice not created',
    message: 'Add at least one of your own receiving addresses in the "Settings" node.' } }];
}
const memo = ('Invoice ' + j.invoiceId + (j.description ? ': ' + j.description : '')).slice(0, 500);
const request = {
  fiatCurrency: j.currency,
  fiatAmount: j.amount,
  orderId: j.invoiceId,
  memo,
  expiryHours: Number(j.expiryHours) || 72,
  reuseOpenForOrder: true,
  options,
};
if (j.declineNote) request.declineNote = String(j.declineNote).slice(0, 200);
// Same invoice + same request = same pay link on a retry. The same key with another
// amount, currency or address is refused with 422 and creates nothing.
return [{ json: { ...j, ok: true, request, idempotencyKey: 'invoice-' + j.invoiceId } }];

// Reads the send21 answer. On success it stores the invoice in this workflow's
// static data (kept between production runs), so the webhook branch can match it.
const res = $input.first().json;
const inv = $('Build payment request').first().json;
const body = res.body || {};
if (res.statusCode >= 200 && res.statusCode < 300 && body.payPath) {
  const payLink = 'https://send21.io' + body.payPath;
  const store = $getWorkflowStaticData('global');
  store.invoices = store.invoices || {};
  // the webhook branch emails you from these
  store.settings = { ownerEmail: inv.ownerEmail, senderEmail: inv.senderEmail };
  store.invoices[inv.invoiceId] = {
    invoiceId: inv.invoiceId,
    paymentRequestId: body.id,
    clientName: inv.clientName,
    clientEmail: inv.clientEmail,
    amount: inv.amount,
    currency: inv.currency,
    description: inv.description,
    payLink,
    expiresAt: body.expiresAt,
    status: (store.invoices[inv.invoiceId] || {}).status === 'paid' ? 'paid' : 'sent',
    createdAt: new Date().toISOString(),
  };
  return [{ json: { ...inv, ok: true, statusCode: 200, title: 'Invoice ' + inv.invoiceId + ' sent',
    payLink, paymentRequestId: body.id, expiresAt: body.expiresAt } }];
}
const text = JSON.stringify(body);
let message = 'send21 answered ' + res.statusCode + ': ' + (body.detail || body.title || text).toString().slice(0, 300);
if (text.includes('address_not_approved')) {
  message = 'One of the receiving addresses in "Settings" is not approved yet. Approve it yourself in the send21 app ' +
    '(address book, with a passkey or authenticator code), then try again. No API key can approve an address.';
} else if (res.statusCode === 402) {
  message = 'send21 asks you to settle accrued fees first (POST /api/v1/fees/accrued/settle, or in the app).';
} else if (res.statusCode === 401 || res.statusCode === 403) {
  message = 'The send21 API key is missing, wrong or lacks the drafts:write scope (or the account owner has not confirmed it yet).';
}
return [{ json: { ...inv, ok: false, statusCode: res.statusCode >= 400 && res.statusCode < 500 ? res.statusCode : 502,
  title: 'Invoice not created', message } }];

// Reports whether the email went out. The pay link is returned either way.
const inv = $('Record invoice').first().json;
const mail = $input.first().json || {};
const emailed = !mail.error;
const message = 'Pay link for ' + inv.amount + ' ' + inv.currency + ': ' + inv.payLink +
  (emailed ? ' (emailed to ' + inv.clientEmail + ')' : ' (email not sent: ' + String(mail.error && (mail.error.message || mail.error)).slice(0, 160) + ')');
return [{ json: { ...inv, emailed, message } }];

// Verifies X-Send21-Signature-V2 = t=<unix>,v1=<hex HMAC-SHA256 of "<t>.<delivery id>.<raw body>">
// over the RAW body, refuses deliveries more than 300 s (5 minutes) old, and flags
// delivery ids this workflow already handled (send21 retries reuse X-Send21-Delivery;
// deduplicating is the receiver's job).
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and SEND21_WEBHOOK_SECRET in the n8n environment.
const crypto = require('crypto');
const secret = $env.SEND21_WEBHOOK_SECRET;
const item = $input.first();
const h = item.json.headers || {};
let raw = null;
if (item.binary && item.binary.data) {
  try {
    raw = await this.helpers.getBinaryDataBuffer(0, 'data');
  } catch (e) {
    raw = item.binary.data.data ? Buffer.from(item.binary.data.data, 'base64') : null;
  }
}
const sig = String(h['x-send21-signature-v2'] || '');
const deliveryId = String(h['x-send21-delivery'] || '');
const t = (/(?:^|,)t=(\d+)/.exec(sig) || [])[1];
const v1 = (/(?:^|,)v1=([0-9a-f]{64})/.exec(sig) || [])[1];
let reason = '';
if (!secret) reason = 'SEND21_WEBHOOK_SECRET is not set';
else if (!raw) reason = 'raw body missing (turn on the Raw Body option of the webhook node)';
else if (!t || !v1 || !deliveryId) reason = 'missing X-Send21-Signature-V2 or X-Send21-Delivery';
else if (Math.abs(Date.now() / 1000 - Number(t)) > 300) reason = 'delivery more than 5 minutes old';
else {
  const expected = crypto.createHmac('sha256', secret).update(t + '.' + deliveryId + '.').update(raw).digest();
  if (!crypto.timingSafeEqual(Buffer.from(v1, 'hex'), expected)) reason = 'signature does not match';
}
if (reason) return [{ json: { valid: false, reason } }];

let payload;
try { payload = JSON.parse(raw.toString('utf8')); } catch (e) { return [{ json: { valid: false, reason: 'body is not JSON' } }]; }
const store = $getWorkflowStaticData('global');
const seen = store.seenDeliveries || {};
return [{ json: {
  valid: true,
  duplicate: Object.prototype.hasOwnProperty.call(seen, deliveryId),
  deliveryId,
  event: payload.event,
  data: payload.data || {},
} }];

// Applies one verified, new delivery to the invoice it belongs to, and records the
// delivery id so a retry of the same delivery is ignored.
const store = $getWorkflowStaticData('global');
store.invoices = store.invoices || {};
store.seenDeliveries = store.seenDeliveries || {};
const { deliveryId, event, data } = $input.first().json;
const inv = (data.orderId && store.invoices[data.orderId]) ||
  Object.values(store.invoices).find((i) => data.paymentRequestId && i.paymentRequestId === data.paymentRequestId) || null;

let action = 'ignore';
let note = '';
if (event === 'draft.confirmed') {
  if (!inv) {
    action = 'unknown';
    note = 'Confirmed payment for orderId ' + data.orderId + ', but this workflow has no such invoice.';
  } else if (data.paymentRequestId && inv.paymentRequestId && data.paymentRequestId !== inv.paymentRequestId) {
    action = 'review';
    note = 'The payment belongs to another pay link (' + data.paymentRequestId + ') than this invoice.';
  } else if (String(data.fiatCurrency || '').toUpperCase() !== inv.currency || Math.abs(Number(data.fiatAmount) - inv.amount) > 0.005) {
    action = 'review';
    note = 'Paid ' + data.fiatAmount + ' ' + data.fiatCurrency + ', but the invoice is ' + inv.amount + ' ' + inv.currency + '.';
  } else if (inv.status === 'paid') {
    action = 'ignore';
    note = 'Invoice was already marked paid.';
  } else {
    action = 'paid';
    Object.assign(inv, { status: 'paid', paidAt: data.occurredAt, txId: data.txId, network: data.network,
      sentCurrency: data.sentCurrency, sentAmount: data.sentAmount, draftId: data.draftId });
    if (data.receivedAmountSats != null) note = 'You accepted a different amount in send21 before it confirmed.';
  }
} else if (event === 'draft.amount_mismatch') {
  action = 'review';
  if (inv && inv.status !== 'paid') inv.status = 'needs your decision';
  note = 'A transfer with a different amount arrived. It is not a payment until YOU accept or decline it in send21. This workflow never decides.';
} else if (event === 'payment_request.expired' && !(inv && inv.status === 'paid')) {
  action = 'expired';
  if (inv) inv.status = 'expired';
  note = 'Opened by the payer: ' + data.opened + '. Picked a currency: ' + data.quoteRequested + '.';
} else if (event === 'test') {
  action = 'test';
}

store.seenDeliveries[deliveryId] = Date.now();
const cutoff = Date.now() - 30 * 24 * 3600 * 1000;
for (const [id, ts] of Object.entries(store.seenDeliveries)) if (ts < cutoff) delete store.seenDeliveries[id];

const ref = inv ? 'Invoice ' + inv.invoiceId + ' (' + inv.amount + ' ' + inv.currency + ', ' + inv.clientName + ')' : 'Order ' + (data.orderId || '?');
const subjects = { paid: ref + ' is paid', review: ref + ' needs your decision', expired: ref + ' expired unpaid', unknown: 'send21: payment for an unknown order' };
const settings = store.settings || {};
return [{ json: {
  action, event, deliveryId, note,
  ownerEmail: settings.ownerEmail || '', senderEmail: settings.senderEmail || '',
  invoice: inv,
  subject: subjects[action] || ref,
  text: [subjects[action] || ref, note,
    data.txId ? 'Transaction: ' + data.txId + ' on ' + data.network + ' (' + data.sentAmount + ' ' + data.sentCurrency + ')' : '',
    inv ? 'Pay link: ' + inv.payLink : ''].filter(Boolean).join('\n'),
} }];
